// Generates apps/android-v2/lib/src/data/curated_packs.g.dart from the web app's
// curated packs so both clients share one list. Run: node tool/gen_curated_packs.mjs
import { writeFileSync } from 'node:fs'
import { CURATED_PACKS } from '../apps/web/app/data/curatedPacks.ts'

const q = s => `'${String(s).replaceAll('\\', '\\\\').replaceAll("'", "\\'").replaceAll('$', '\\$')}'`
const hex = c => `0xFF${c.replace('#', '').toUpperCase()}`
const lines = [
  '// GENERATED by tool/gen_curated_packs.mjs from apps/web/app/data/curatedPacks.ts.',
  '// Do not edit by hand.',
  '// ignore_for_file: lines_longer_than_80_chars',
  '',
  "import 'curated_pack.dart';",
  '',
  'const curatedPacks = <CuratedPack>[',
]
for (const p of CURATED_PACKS) {
  lines.push('  CuratedPack(')
  lines.push(`    id: ${q(p.id)},`, `    title: ${q(p.title)},`, `    description: ${q(p.description)},`)
  lines.push(`    minMatches: ${p.minMatches},`, `    wave: ${q(p.wave)},`)
  if (p.season) {
    const s = p.season
    lines.push(`    season: PackSeason(${s.startMonth}, ${s.startDay}, ${s.endMonth}, ${s.endDay}),`)
  }
  lines.push(`    theme: CuratedTheme(bg: ${hex(p.theme.bg)}, accent: ${hex(p.theme.accent)}, mid: ${hex(p.theme.mid)}, label: ${hex(p.theme.label)}),`)
  lines.push('    entries: [')
  for (const e of p.entries) {
    const f = [`name: ${q(e.name)}`]
    if (e.imdb) f.push(`imdb: ${q(e.imdb)}`)
    if (e.tmdb) f.push(`tmdb: ${q(e.tmdb)}`)
    if (e.year != null) f.push(`year: ${e.year}`)
    if (e.type) f.push(`type: ${q(e.type)}`)
    lines.push(`      PackEntry(${f.join(', ')}),`)
  }
  lines.push('    ],', '  ),')
}
lines.push('];', '')
writeFileSync(new URL('../apps/android-v2/lib/src/data/curated_packs.g.dart', import.meta.url), lines.join('\n'))
console.log(`wrote ${CURATED_PACKS.length} packs`)
